arguments.content:
/* ============================================================
   MULTIPLIER — a field guide to doing the most good
   ============================================================ */

:root {
  --bg: #0b0c0a;
  --bg-2: #10120e;
  --panel: #121410;
  --ink: #f1efe5;
  --muted: #a5a598;
  --faint: #727368;
  --line: rgba(241, 239, 229, 0.13);
  --line-soft: rgba(241, 239, 229, 0.07);
  --lime: #d8f26b;
  --lime-dim: #a9c043;
  --cyan: #7ce0cf;
  --amber: #f0a35e;
  --rose: #ef8b7c;
  --serif: "Iowan Old Style", "Palatino Linotype", Palatino, "Book Antiqua", Georgia, "Times New Roman", serif;
  --sans: "Inter", "Helvetica Neue", Helvetica, Arial, system-ui, sans-serif;
  --mono: "SFMono-Regular", "SF Mono", ui-monospace, Menlo, Consolas, "Liberation Mono", monospace;
  --ease: cubic-bezier(0.16, 1, 0.3, 1);
  --radius: 18px;
  --max: 1240px;
}

* { box-sizing: border-box; }

html {
  scroll-behavior: smooth;
  scroll-padding-top: 84px;
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--sans);
  font-size: 16px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overflow-x: hidden;
}

body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  background:
    radial-gradient(700px 460px at 82% 4%, rgba(216, 242, 107, 0.055), transparent 70%),
    radial-gradient(800px 600px at 6% 42%, rgba(124, 224, 207, 0.04), transparent 70%);
}

::selection { background: var(--lime); color: #0b0c0a; }

a { color: inherit; text-decoration: none; }

h1, h2, h3 { margin: 0; font-weight: 400; }

p { margin: 0; }

button, input, select { font: inherit; color: inherit; }

button { cursor: pointer; }

main { position: relative; z-index: 1; }

.container {
  width: min(var(--max), calc(100% - 80px));
  margin: 0 auto;
}

.skip {
  position: absolute;
  left: -9999px;
  top: 0;
  z-index: 100;
  background: var(--lime);
  color: #0b0c0a;
  padding: 12px 20px;
  border-radius: 0 0 12px 0;
  font-weight: 600;
}
.skip:focus { left: 0; }

/* ------------------------------ shared type ----------------------------- */

.mono { font-family: var(--mono); font-size: 11px; letter-spacing: 0.12em; text-transform: uppercase; }
.dim { color: var(--faint); }
.tiny { font-size: 10px; }
.serif { font-family: var(--serif); }

.eyebrow {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 28px;
}
.eyebrow .dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--lime);
  box-shadow: 0 0 0 4px rgba(216, 242, 107, 0.12);
  flex: none;
}

.section { position: relative; padding: 130px 0; }
.section + .section { border-top: 1px solid var(--line-soft); }

.section-head { max-width: 900px; margin-bottom: 64px; }
.section-head h2 {
  font-family: var(--serif);
  font-size: clamp(38px, 5.1vw, 72px);
  line-height: 0.99;
  letter-spacing: -0.028em;
  margin-bottom: 28px;
}
.section-head h2 em { font-style: italic; color: var(--lime); }

.section-head.split {
  max-width: none;
  display: grid;
  grid-template-columns: 1.2fr 0.8fr;
  gap: 72px;
  align-items: end;
}
.section-head.split h2 { margin-bottom: 0; }

.lede {
  font-size: 17px;
  line-height: 1.65;
  color: var(--muted);
  max-width: 62ch;
}
.lede.side { padding-bottom: 6px; max-width: 44ch; }

.fineprint {
  font-size: 12.5px;
  line-height: 1.6;
  color: var(--faint);
  max-width: 74ch;
  margin-top: 36px;
}
.fineprint.tight { margin-top: 20px; font-size: 11.5px; }
.fineprint a { color: var(--muted); border-bottom: 1px solid var(--line); }
.fineprint a:hover { color: var(--lime); }

/* -------------------------------- buttons ------------------------------- */

.btn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 14px 24px;
  border-radius: 999px;
  border: 1px solid transparent;
  font-size: 13.5px;
  font-weight: 600;
  letter-spacing: 0.01em;
  transition: transform 0.35s var(--ease), background 0.25s, border-color 0.25s, box-shadow 0.35s;
  white-space: nowrap;
}
.btn-primary {
  background: var(--lime);
  color: #0b0c0a;
  box-shadow: 0 0 0 rgba(216, 242, 107, 0);
}
.btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 12px 36px -10px rgba(216, 242, 107, 0.55);
}
.btn-ghost {
  border-color: var(--line);
  color: var(--ink);
  background: rgba(255, 255, 255, 0.015);
}
.btn-ghost:hover { border-color: rgba(216, 242, 107, 0.5); transform: translateY(-2px); }

.text-btn {
  background: none;
  border: none;
  padding: 0;
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--faint);
  border-bottom: 1px solid transparent;
  transition: color 0.2s, border-color 0.2s;
}
.text-btn:hover { color: var(--lime); border-color: var(--lime); }

.chip {
  background: transparent;
  border: 1px solid var(--line);
  color: var(--muted);
  border-radius: 999px;
  padding: 7px 13px;
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.08em;
  transition: all 0.22s var(--ease);
}
.chip:hover { color: var(--ink); border-color: rgba(241, 239, 229, 0.32); }
.chip.is-active { background: var(--lime); color: #0b0c0a; border-color: var(--lime); }

/* ---------------------------------- nav -------------------------------- */

.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 50;
  background: rgba(11, 12, 10, 0.72);
  -webkit-backdrop-filter: blur(18px);
  backdrop-filter: blur(18px);
  border-bottom: 1px solid var(--line-soft);
}
.nav-inner {
  width: min(var(--max), calc(100% - 80px));
  margin: 0 auto;
  height: 68px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  font-family: var(--mono);
  font-size: 12px;
  letter-spacing: 0.16em;
  font-weight: 600;
}
.brand-mark {
  color: var(--lime);
  font-size: 17px;
  line-height: 1;
  animation: spin 18s linear infinite;
  display: inline-block;
}
@keyframes spin { to { transform: rotate(360deg); } }

.nav-links { display: flex; gap: 26px; }
.nav-links a {
  font-size: 12.5px;
  color: var(--muted);
  transition: color 0.2s;
  position: relative;
}
.nav-links a::after {
  content: "";
  position: absolute;
  left: 0; bottom: -5px;
  width: 100%; height: 1px;
  background: var(--lime);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.3s var(--ease);
}
.nav-links a:hover { color: var(--ink); }
.nav-links a:hover::after { transform: scaleX(1); }

.nav-cta {
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--lime);
  border: 1px solid rgba(216, 242, 107, 0.35);
  padding: 9px 15px;
  border-radius: 999px;
  transition: all 0.25s;
}
.nav-cta:hover { background: var(--lime); color: #0b0c0a; }

/* --------------------------------- hero -------------------------------- */

.hero {
  position: relative;
  min-height: 100svh;
  display: flex;
  align-items: center;
  padding: 130px 0 90px;
  overflow: hidden;
}
.hero::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  background-image:
    linear-gradient(to right, rgba(241, 239, 229, 0.045) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(241, 239, 229, 0.045) 1px, transparent 1px);
  background-size: 96px 96px;
  mask-image: radial-gradient(ellipse 75% 60% at 30% 35%, #000 20%, transparent 75%);
  -webkit-mask-image: radial-gradient(ellipse 75% 60% at 30% 35%, #000 20%, transparent 75%);
  opacity: 0.7;
}
.hero-glow {
  position: absolute;
  width: 900px; height: 900px;
  right: -220px; top: -260px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(216, 242, 107, 0.09), transparent 62%);
  filter: blur(20px);
  pointer-events: none;
}
.hero-grid {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  gap: 72px;
  align-items: center;
}
.hero-copy h1 {
  font-family: var(--serif);
  font-size: clamp(50px, 7.4vw, 108px);
  line-height: 0.9;
  letter-spacing: -0.035em;
  margin: 0 0 32px;
}
.hero-copy h1 em {
  font-style: italic;
  color: var(--lime);
  position: relative;
}
.hero-lede {
  font-size: 17.5px;
  line-height: 1.62;
  color: var(--muted);
  max-width: 52ch;
  margin-bottom: 38px;
}
.hero-actions { display: flex; gap: 14px; flex-wrap: wrap; margin-bottom: 60px; }

.hero-stats {
  list-style: none;
  display: flex;
  gap: 40px;
  padding: 26px 0 0;
  margin: 0;
  border-top: 1px solid var(--line);
}
.hero-stats li { display: flex; flex-direction: column; gap: 4px; }
.stat-num {
  font-family: var(--mono);
  font-size: 22px;
  letter-spacing: -0.02em;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}
.stat-label { font-size: 11.5px; line-height: 1.35; color: var(--faint); }

.hero-panel {
  border: 1px solid var(--line);
  border-radius: 22px;
  background:
    linear-gradient(160deg, rgba(255, 255, 255, 0.045), rgba(255, 255, 255, 0.008) 55%),
    var(--panel);
  padding: 20px 20px 22px;
  box-shadow: 0 50px 120px -60px rgba(0, 0, 0, 0.9), inset 0 1px 0 rgba(255, 255, 255, 0.05);
  position: relative;
  overflow: hidden;
}
.hero-panel::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 22px;
  pointer-events: none;
  background: radial-gradient(400px 200px at 80% 0%, rgba(216, 242, 107, 0.07), transparent 70%);
}
.panel-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: var(--muted);
  margin-bottom: 14px;
}
.dotfield-wrap {
  position: relative;
  width: 100%;
  aspect-ratio: 2 / 1.12;
  border-radius: 12px;
  overflow: hidden;
  background: radial-gradient(ellipse at 50% 45%, #181b12 0%, #0d0f0b 70%);
  border: 1px solid var(--line-soft);
}
#dotfield { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
.panel-foot {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 20px;
  margin-top: 16px;
}
.panel-foot p { font-size: 11.5px; line-height: 1.5; color: var(--faint); max-width: 34ch; }
.panel-foot strong { color: var(--ink); font-weight: 500; }
.panel-foot .tiny { flex: none; text-align: right; color: var(--faint); }

.scroll-hint {
  position: absolute;
  bottom: 26px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--faint);
}
.scroll-hint span {
  width: 26px; height: 1px; background: var(--faint);
  position: relative; overflow: hidden;
}
.scroll-hint span::after {
  content: ""; position: absolute; inset: 0; background: var(--lime);
  transform: translateX(-100%); animation: sweep 2.4s ease-in-out infinite;
}
@keyframes sweep { 50% { transform: translateX(0); } 100% { transform: translateX(100%); } }

/* ------------------------------ exchange ------------------------------- */

.exchange .section-head h2 { max-width: 15ch; }
.ledger {
  border-top: 1px solid var(--line);
  margin-top: 12px;
}
.ledger-head, .ledger-row {
  display: grid;
  grid-template-columns: 150px 1fr 1.15fr;
  gap: 32px;
  align-items: baseline;
}
.ledger-head {
  padding: 14px 0;
  color: var(--faint);
  border-bottom: 1px solid var(--line-soft);
}
.ledger-row {
  padding: 22px 0;
  border-bottom: 1px solid var(--line-soft);
  position: relative;
  transition: background 0.3s, padding 0.3s var(--ease);
}
.ledger-row::before {
  content: "";
  position: absolute; left: -20px; top: 0; bottom: 0; width: 2px;
  background: var(--lime);
  transform: scaleY(0);
  transition: transform 0.3s var(--ease);
}
.ledger-row:hover { background: rgba(255, 255, 255, 0.022); padding-left: 16px; }
.ledger-row:hover::before { transform: scaleY(0.55); }
.ledger-amt {
  font-family: var(--mono);
  font-size: clamp(19px, 2vw, 27px);
  letter-spacing: -0.03em;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}
.ledger-what { font-size: 15px; color: var(--faint); }
.ledger-alt { font-size: 15px; color: var(--muted); }
.ledger-alt b { color: var(--ink); font-weight: 500; }
.ledger-row.is-key { background: linear-gradient(90deg, rgba(216, 242, 107, 0.055), transparent 65%); }
.ledger-row.is-key .ledger-amt { color: var(--lime); }
.ledger-row.is-key .ledger-alt b { color: var(--lime); }

/* --------------------------------- lab --------------------------------- */

.lab-grid {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  gap: 32px;
  align-items: stretch;
}
.lab-controls, .lab-output {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 30px;
  background: linear-gradient(165deg, rgba(255, 255, 255, 0.035), rgba(255, 255, 255, 0.006));
}
.lab-controls { display: flex; flex-direction: column; gap: 30px; }

.control-block { display: flex; flex-direction: column; gap: 14px; }
.control-label {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 16px;
  font-size: 13px;
  color: var(--muted);
}
.big-out {
  color: var(--lime);
  font-size: 22px;
  letter-spacing: -0.02em;
  font-variant-numeric: tabular-nums;
}

/* range */
input[type="range"] {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 24px;
  background: transparent;
  cursor: pointer;
  margin: 0;
}
input[type="range"]::-webkit-slider-runnable-track {
  height: 3px;
  border-radius: 2px;
  background: linear-gradient(90deg, var(--lime) 0%, var(--lime) var(--fill, 45%), rgba(241, 239, 229, 0.14) var(--fill, 45%), rgba(241, 239, 229, 0.14) 100%);
}
input[type="range"]::-moz-range-track {
  height: 3px;
  border-radius: 2px;
  background: rgba(241, 239, 229, 0.14);
}
input[type="range"]::-moz-range-progress {
  height: 3px;
  border-radius: 2px;
  background: var(--lime);
}
input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 16px; height: 16px;
  border-radius: 50%;
  background: var(--lime);
  border: 3px solid #0b0c0a;
  box-shadow: 0 0 0 1px var(--lime), 0 0 22px rgba(216, 242, 107, 0.45);
  margin-top: -6.5px;
  transition: transform 0.15s;
}
input[type="range"]:active::-webkit-slider-thumb { transform: scale(1.18); }
input[type="range"]::-moz-range-thumb {
  width: 14px; height: 14px;
  border-radius: 50%;
  background: var(--lime);
  border: 3px solid #0b0c0a;
  box-shadow: 0 0 0 1px var(--lime);
}
input[type="range"]:focus-visible { outline: none; }
input[type="range"]:focus-visible::-webkit-slider-thumb { box-shadow: 0 0 0 3px rgba(216, 242, 107, 0.35); }

.range-scale {
  display: flex;
  justify-content: space-between;
  color: var(--faint);
  font-size: 9px;
  letter-spacing: 0.1em;
}
.quick-row { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 2px; }

.mix { display: flex; flex-direction: column; gap: 16px; }
.mix-row { display: grid; grid-template-columns: 78px 1fr 40px; align-items: center; gap: 14px; }
.mix-name { font-size: 12.5px; color: var(--muted); display: flex; align-items: center; gap: 8px; }
.mix-dot { width: 6px; height: 6px; border-radius: 50%; flex: none; }
.mix-val { font-family: var(--mono); font-size: 11px; color: var(--ink); text-align: right; font-variant-numeric: tabular-nums; }
.mix-row input[type="range"] { height: 20px; }

.allocation-bar {
  display: flex;
  height: 10px;
  border-radius: 99px;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.06);
  margin-bottom: 12px;
}
.seg { transition: width 0.6s var(--ease); }
.seg-health { background: var(--lime); }
.seg-climate { background: var(--cyan); }
.seg-animals { background: var(--amber); }
.allocation-legend {
  display: flex;
  gap: 20px;
  flex-wrap: wrap;
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: 0.08em;
  color: var(--faint);
  margin-bottom: 34px;
}
.allocation-legend span { display: inline-flex; align-items: center; gap: 7px; }
.allocation-legend i { width: 7px; height: 7px; border-radius: 2px; display: inline-block; }

.outcome-primary { border-bottom: 1px solid var(--line); padding-bottom: 30px; margin-bottom: 28px; }
.outcome-label { color: var(--faint); margin-bottom: 6px; }
.outcome-number {
  font-family: var(--serif);
  font-size: clamp(62px, 8vw, 104px);
  line-height: 0.92;
  letter-spacing: -0.04em;
  color: var(--lime);
  font-variant-numeric: tabular-nums;
  display: flex;
  align-items: baseline;
  gap: 14px;
}
.outcome-number small { font-family: var(--sans); font-size: 16px; letter-spacing: 0; color: var(--muted); }
.outcome-sub { margin-top: 12px; font-size: 13.5px; color: var(--muted); }

.outcome-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1px;
  background: var(--line-soft);
  border: 1px solid var(--line-soft);
  border-radius: 12px;
  overflow: hidden;
}
.outcome-tile {
  background: var(--panel);
  padding: 18px 18px 20px;
  display: flex;
  flex-direction: column;
  gap: 7px;
}
.tile-label { color: var(--faint); font-size: 9px; }
.outcome-value {
  font-family: var(--serif);
  font-size: clamp(24px, 2.4vw, 32px);
  line-height: 1;
  letter-spacing: -0.02em;
  font-variant-numeric: tabular-nums;
}
.tile-sub { font-size: 10.5px; line-height: 1.4; color: var(--faint); }

/* -------------------------------- atlas -------------------------------- */

.atlas-toolbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 24px;
  flex-wrap: wrap;
  margin-bottom: 32px;
  padding-bottom: 22px;
  border-bottom: 1px solid var(--line);
}
.filters { display: flex; gap: 8px; flex-wrap: wrap; }
.sort-wrap { display: flex; align-items: center; gap: 12px; }
.sort-wrap label { color: var(--faint); }
select {
  -webkit-appearance: none;
  appearance: none;
  background: transparent;
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 8px 34px 8px 14px;
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted);
  background-image: linear-gradient(45deg, transparent 50%, var(--faint) 50%), linear-gradient(135deg, var(--faint) 50%, transparent 50%);
  background-position: calc(100% - 17px) 52%, calc(100% - 12px) 52%;
  background-size: 5px 5px, 5px 5px;
  background-repeat: no-repeat;
  cursor: pointer;
}
select:hover { border-color: rgba(241, 239, 229, 0.3); color: var(--ink); }
select option { background: #161811; color: var(--ink); }

.atlas-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}

.card {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 18px;
  padding: 24px 22px 20px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: linear-gradient(165deg, rgba(255, 255, 255, 0.035), rgba(255, 255, 255, 0.005));
  transition: border-color 0.3s, transform 0.4s var(--ease), background 0.3s;
  overflow: hidden;
}
.card::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(320px 160px at 100% 0%, rgba(216, 242, 107, 0.055), transparent 70%);
  opacity: 0;
  transition: opacity 0.4s;
}
.card:hover {
  border-color: rgba(241, 239, 229, 0.26);
  transform: translateY(-4px);
}
.card:hover::after { opacity: 1; }
.card.is-selected {
  border-color: rgba(216, 242, 107, 0.55);
  background: linear-gradient(165deg, rgba(216, 242, 107, 0.07), rgba(255, 255, 255, 0.005));
}

.card-top { display: flex; justify-content: space-between; align-items: center; gap: 12px; }
.card-cat {
