  // Build the three cause sliders
  const rows = {};
  CAUSES.forEach((cause) => {
    const row = document.createElement('div');
    row.className = 'mix-row';

    const name = document.createElement('span');
    name.className = 'mix-name';
    name.innerHTML = `<i class="mix-dot" style="background:${cause.color}"></i>${cause.name}`;

    const input = document.createElement('input');
    input.type = 'range';
    input.min = '0';
    input.max = '100';
    input.step = '1';
    input.value = String(Math.round(mix[cause.id]));
    input.setAttribute('aria-label', `${cause.name} share of giving`);
    input.dataset.cause = cause.id;

    const val = document.createElement('span');
    val.className = 'mix-val';
    val.textContent = Math.round(mix[cause.id]) + '%';

    row.append(name, input, val);
    mixEl.append(row);
    rows[cause.id] = { input, val };
  });

  function setFill(input) {
    const min = Number(input.min) || 0;
    const max = Number(input.max) || 100;
    const v = Number(input.value);
    const pct = ((v - min) / (max - min)) * 100;
    input.style.setProperty('--fill', `${pct}%`);
  }

  function setShare(id, raw) {
    const v = clamp(Number(raw), 0, 100);
    const others = CAUSES.map((c) => c.id).filter((k) => k !== id);
    const rest = 100 - v;
    const otherSum = others.reduce((s, k) => s + mix[k], 0);
    mix[id] = v;
    if (otherSum <= 0.0001) {
      others.forEach((k) => { mix[k] = rest / others.length; });
    } else {
      others.forEach((k) => { mix[k] = (mix[k] / otherSum) * rest; });
    }
    // guard against float drift
    const total = CAUSES.reduce((s, c) => s + mix[c.id], 0);
    if (total > 0) {
      const f = 100 / total;
      CAUSES.forEach((c) => { mix[c.id] *= f; });
    }
    syncMixUI();
    update();
  }

  function syncMixUI() {
    CAUSES.forEach((c) => {
      const { input, val } = rows[c.id];
      input.value = String(Math.round(mix[c.id]));
      val.textContent = Math.round(mix[c.id]) + '%';
      setFill(input);
    });
  }

  function setMixPreset(key) {
    mix = { ...MIX_PRESETS[key] };
    syncMixUI();
    update();
    document.querySelectorAll('#mix-presets .chip').forEach((b) => {
      b.classList.toggle('is-active', b.dataset.mix === key);
    });
  }

  // Bind sliders
  Object.values(rows).forEach(({ input }) => {
    input.addEventListener('input', () => setShare(input.dataset.cause, input.value));
  });

  document.querySelectorAll('#mix-presets .chip').forEach((btn) => {
    btn.addEventListener('click', () => setMixPreset(btn.dataset.mix));
  });
  document.querySelector('#reset-mix').addEventListener('click', () => {
    mix = { ...DEFAULT_MIX };
    syncMixUI();
    update();
    document.querySelectorAll('#mix-presets .chip').forEach((b) => b.classList.remove('is-active'));
  });

  document.querySelectorAll('#budget-presets .chip').forEach((btn) => {
    btn.addEventListener('click', () => {
      budget.value = btn.dataset.budget;
      value = Number(budget.value);
      setFill(budget);
      update();
      document.querySelectorAll('#budget-presets .chip').forEach((b) => {
        b.classList.toggle('is-active', b === btn);
      });
    });
  });

  budget.addEventListener('input', () => {
    value = Number(budget.value);
    setFill(budget);
    update();
    document.querySelectorAll('#budget-presets .chip').forEach((b) => b.classList.remove('is-active'));
  });

  function update() {
    const total = CAUSES.reduce((s, c) => s + mix[c.id], 0) || 1;
    const share = {};
    CAUSES.forEach((c) => { share[c.id] = mix[c.id] / total; });

    const healthMoney = value * share.health;
    const climateMoney = value * share.climate;
    const animalMoney = value * share.animals;

    const qaly = healthMoney / HEALTH_COST_PER_QALY;
    const co2 = climateMoney / CLIMATE_COST_PER_TONNE;
    const animalCount = animalMoney / ANIMAL_COST_PER_ANIMAL;
    const lifeCount = qaly / YEARS_PER_LIFE;
    const per100 = (share.health / HEALTH_COST_PER_QALY) * 100;

    budgetOut.textContent = money(value);
    animateNumber(qalyOut, qaly, (v) => (v >= 100 ? int(v) : v.toFixed(1)));
    animateNumber(co2Out, co2, tonnes);
    animateNumber(animalsOut, animalCount, animals);
    animateNumber(per100Out, per100, (v) => (v < 0.1 ? v.toFixed(2) : v.toFixed(1)) + ' yr');

    if (lifeCount >= 0.01) {
      const perLife = value / lifeCount;
      livesOut.textContent = `≈ ${lives(lifeCount)} ${lifeCount > 1.6 ? 'lives' : 'lives'} — one life for every ${money(Math.round(perLife / 100) * 100)} given`;
    } else {
      livesOut.textContent = 'Move the budget to begin — every $100 is about a healthy year.';
    }

    co2Sub.textContent = co2 >= 0.05
      ? `≈ ${(co2 / 1.6).toFixed(1)} transatlantic flights avoided`
      : '≈ a short car trip';

    animalsSub.textContent = animalCount >= 1
      ? `≈ ${animals(animalCount)} animals out of cages for a year`
      : 'no animal-welfare allocation yet';

    seg.health.style.width = (share.health * 100).toFixed(2) + '%';
    seg.climate.style.width = (share.climate * 100).toFixed(2) + '%';
    seg.animals.style.width = (share.animals * 100).toFixed(2) + '%';

    legend.innerHTML = CAUSES.map((c) => {
      const amount = value * share[c.id];
      return `<span><i style="background:${c.color}"></i>${c.name} ${Math.round(share[c.id] * 100)}% · ${money(amount)}</span>`;
    }).join('');

    // sync the "per $100" equivalent lines for transparency
    if (co2 >= 0.05) {
      co2Sub.title = `${int(co2)} tonnes CO2e`;
    }
  }

  setFill(budget);
  syncMixUI();
  setMixPreset('balanced');
}

// expose for the portfolio summary if needed
export { DEFAULT_MIX };

import { ACTION_BY_ID, YEARS_PER_LIFE } from './data.js';
import { animateNumber, int, compact, lives, tonnes, animals } from './format.js';

const SCALES = [
  { label: 'Just me', value: 1 },
  { label: '×1,000', value: 1000 },
  { label: '×1M', value: 1e6 },
  { label: '×1B', value: 1e9 },
  { label: 'Everyone', value: 8e9 },
];

const state = {
  selected: new Set(['give1000', 'talk']),
  scale: 0,
};

const listeners = new Set();
const subscribe = (fn) => { listeners.add(fn); return () => listeners.delete(fn); };
const emit = () => listeners.forEach((fn) => fn());

export const isSelected = (id) => state.selected.has(id);

export function toggleAction(id) {
  if (!ACTION_BY_ID[id]) return;
  if (state.selected.has(id)) state.selected.delete(id);
  else state.selected.add(id);
  emit();
}

export function removeAction(id) {
  state.selected.delete(id);
  emit();
}

export function clearActions() {
  state.selected.clear();
  emit();
}

let wired = false;

export function initPortfolio() {
  const panel = document.querySelector('#portfolio-panel');
  if (!panel) return;

  const empty = document.querySelector('#portfolio-empty');
  const content = document.querySelector('#portfolio-content');
  const countEl = document.querySelector('#portfolio-count');
  const scaleRow = document.querySelector('#scale-row');
  const qalyEl = document.querySelector('#p-qaly');
  const livesEl = document.querySelector('#p-lives');
  const co2El = document.querySelector('#p-co2');
  const co2Sub = document.querySelector('#p-co2-sub');
  const animalsEl = document.querySelector('#p-animals');
  const summaryEl = document.querySelector('#portfolio-summary');
  const copyBtn = document.querySelector('#copy-summary');
  const clearBtn = document.querySelector('#clear-portfolio');

  // scale buttons
  SCALES.forEach((s, i) => {
    const b = document.createElement('button');
    b.type = 'button';
    b.textContent = s.label;
    b.addEventListener('click', () => {
      state.scale = i;
      syncScale();
      render();
    });
    b.dataset.scale = String(i);
    scaleRow.append(b);
  });

  function syncScale() {
    [...scaleRow.children].forEach((b, i) => {
      b.classList.toggle('is-active', i === state.scale);
      b.setAttribute('aria-pressed', i === state.scale ? 'true' : 'false');
    });
  }

  function totals() {
    let qaly = 0, co2 = 0, animalCount = 0;
    for (const id of state.selected) {
      const a = ACTION_BY_ID[id];
      if (!a) continue;
      qaly += a.qaly || 0;
      co2 += a.co2 || 0;
      animalCount += a.animals || 0;
    }
    const m = SCALES[state.scale].value;
    return {
      qaly: qaly * m,
      co2: co2 * m,
      animals: animalCount * m,
      raw: { qaly, co2, animals: animalCount },
      multiplier: m,
      count: state.selected.size,
    };
  }

  function fmtBig(n, kind) {
    if (n >= 1e6) return compact(n);
    if (kind === 'qaly') return n >= 100 ? int(n) : n.toFixed(1);
    if (kind === 'co2') return tonnes(n).replace(' t', ' t');
    return animals(n);
  }

  function summaryText(t) {
    const names = [...state.selected].map((id) => ACTION_BY_ID[id]?.title).filter(Boolean);
    if (!names.length) return '—';
    const verb = names.length === 1 ? 'action' : 'actions';
    let s = `I'm committing to ${names.length} ${verb}: ${names.join('; ')}.`;
    s += ` Together they add up to about ${int(t.raw.qaly)} healthy years, ${int(t.raw.co2)} tonnes of CO₂e avoided and ${int(t.raw.animals)} animals spared each year.`;
    if (state.scale > 0) {
      s += ` At ${SCALES[state.scale].label === 'Everyone' ? 'the scale of everyone' : SCALES[state.scale].label.replace('×', '×')}, that becomes ${fmtBig(t.qaly, 'qaly')} healthy years, ${fmtBig(t.co2, 'co2')} of CO₂e and ${fmtBig(t.animals, 'animals')} animals.`;
    }
    s += ' Estimates, not guarantees — and a reason to start.';
    return s;
  }

  function render() {
    const t = totals();
    const emptyNow = t.count === 0;
    empty.hidden = !emptyNow;
    content.hidden = emptyNow;
    countEl.textContent = `${t.count} ${t.count === 1 ? 'action' : 'actions'}`;

    if (emptyNow) return;

    animateNumber(qalyEl, t.qaly, (v) => fmtBig(v, 'qaly'));
    animateNumber(co2El, t.co2, (v) => fmtBig(v, 'co2'));
    animateNumber(animalsEl, t.animals, (v) => fmtBig(v, 'animals'));

    livesEl.textContent = `≈ ${lives(t.qaly / YEARS_PER_LIFE)} lives, at 45 healthy years each`;
    co2Sub.textContent = `≈ ${compact(t.co2 / 4.6)} cars off the road for a year`;
    summaryEl.textContent = summaryText(t);
  }

  scaleRow.addEventListener('click', () => {});
  syncScale();
  render();
  subscribe(render);

  clearBtn.addEventListener('click', () => {
    clearActions();
  });

  if (!wired) {
    wired = true;
    copyBtn.addEventListener('click', async () => {
      const text = summaryEl.textContent;
      try {
        await navigator.clipboard.writeText(text);
        const old = copyBtn.textContent;
        copyBtn.textContent = 'Copied ✓';
        setTimeout(() => { copyBtn.textContent = old; }, 1800);
      } catch {
        const ta = document.createElement('textarea');
        ta.value = text;
        ta.style.position = 'fixed';
        ta.style.opacity = '0';
        document.body.append(ta);
        ta.select();
        let ok = false;
        try { ok = document.execCommand('copy'); } catch { ok = false; }
        ta.remove();
        copyBtn.textContent = ok ? 'Copied ✓' : 'Select the text above to copy';
        setTimeout(() => { copyBtn.textContent = 'Copy summary'; }, 2200);
      }
    });
  }
}

