import { ACTIONS, CATEGORIES, CATEGORY_COLORS } from './data.js';
import { isSelected, toggleAction, subscribe } from './portfolio.js';
import { int } from './format.js';

const state = { filter: 'All', sort: 'leverage' };

export function initAtlas() {
  const grid = document.querySelector('#atlas-grid');
  const filtersEl = document.querySelector('#filters');
  const sortEl = document.querySelector('#sort');
  if (!grid) return;

  // filters
  const counts = { All: ACTIONS.length };
  ACTIONS.forEach((a) => { counts[a.category] = (counts[a.category] || 0) + 1; });

  CATEGORIES.forEach((cat) => {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'chip' + (cat === 'All' ? ' is-active' : '');
    b.dataset.cat = cat;
    b.textContent = `${cat} ${counts[cat] || 0}`;
    b.addEventListener('click', () => {
      state.filter = cat;
      [...filtersEl.children].forEach((c) => c.classList.toggle('is-active', c === b));
      render();
    });
    filtersEl.append(b);
  });

  sortEl.addEventListener('change', () => {
    state.sort = sortEl.value;
    render();
  });

  function sortActions(list) {
    const s = state.sort;
    return [...list].sort((a, b) => {
      if (s === 'effort') return a.effort - b.effort || b.leverage - a.leverage;
      if (s === 'qaly') return b.qaly - a.qaly || b.leverage - a.leverage;
      if (s === 'co2') return b.co2 - a.co2 || b.leverage - a.leverage;
      if (s === 'animals') return b.animals - a.animals || b.leverage - a.leverage;
      return b.leverage - a.leverage;
    });
  }

  function metrics(a) {
    const chips = [];
    if (a.qaly > 0) chips.push(`<span class="metric"><b>${a.qaly >= 10 ? int(a.qaly) : a.qaly.toFixed(1)}</b> healthy yrs</span>`);
    if (a.co2 > 0) chips.push(`<span class="metric"><b>${a.co2 >= 10 ? int(a.co2) : a.co2.toFixed(1)}</b> t CO₂e</span>`);
    if (a.animals > 0) chips.push(`<span class="metric"><b>${int(a.animals)}</b> animals</span>`);
    if (!chips.length) chips.push('<span class="metric neg">systemic — not quantified</span>');
    return chips.join('');
  }

  function costLabel(c) {
    return ['Free', '$', '$$', '$$$'][c] || '$';
  }

  function effortDots(n) {
    return `<span class="effort" title="Effort: ${n} of 3" aria-label="Effort ${n} of 3">${
      [1, 2, 3].map((i) => `<i class="${i <= n ? 'on' : ''}"></i>`).join('')
    }</span>`;
  }

  function render() {
    const list = sortActions(state.filter === 'All' ? ACTIONS : ACTIONS.filter((a) => a.category === state.filter));
    grid.innerHTML = list.map((a) => {
      const color = CATEGORY_COLORS[a.category] || 'var(--lime)';
      const selected = isSelected(a.id);
      return `
        <article class="card${selected ? ' is-selected' : ''}" data-id="${a.id}">
          <div class="card-top">
            <span class="card-cat"><i class="cat-dot" style="background:${color}"></i>${a.category}</span>
            <button class="add-btn${selected ? ' is-on' : ''}" data-add="${a.id}"
              aria-pressed="${selected}" aria-label="${selected ? 'Remove' : 'Add'} ${a.title} to your portfolio">
              ${selected ? '✓' : '+'}
            </button>
          </div>
          <h3>${a.title}</h3>
          <p class="card-blurb">${a.blurb}</p>
          <div class="card-detail">
            <div>
              <p><b>Why it works.</b> ${a.why}</p>
              <p><b>How to start.</b> ${a.how}</p>
              <p class="src">Source: ${a.source}</p>
            </div>
          </div>
          <div class="card-metrics">${metrics(a)}</div>
          <div class="card-actions">
            <span class="evidence" data-level="${a.evidence}"><i></i>${a.evidence} evidence</span>
            <button class="detail-toggle" data-detail="${a.id}" aria-expanded="false">Why this works +</button>
          </div>
          <div class="card-foot">
            <span>Effort ${effortDots(a.effort)}</span>
            <span>Cost ${costLabel(a.cost)}</span>
          </div>
        </article>`;
    }).join('');
  }

  // event delegation
  grid.addEventListener('click', (e) => {
    const add = e.target.closest('[data-add]');
    if (add) {
      toggleAction(add.dataset.add);
      return;
    }
    const det = e.target.closest('[data-detail]');
    if (det) {
      const card = det.closest('.card');
      const open = card.classList.toggle('is-open');
      det.setAttribute('aria-expanded', open ? 'true' : 'false');
      det.textContent = open ? 'Close −' : 'Why this works +';
    }
  });

  // selection changes from the portfolio side (e.g. clear all)
  subscribe(() => {
    grid.querySelectorAll('.card').forEach((card) => {
      const on = isSelected(card.dataset.id);
      card.classList.toggle('is-selected', on);
      const btn = card.querySelector('[data-add]');
      if (btn) {
        btn.classList.toggle('is-on', on);
        btn.setAttribute('aria-pressed', on ? 'true' : 'false');
        btn.textContent = on ? '✓' : '+';
        btn.setAttribute('aria-label', `${on ? 'Remove' : 'Add'} ${card.querySelector('h3').textContent} ${on ? 'from' : 'to'} your portfolio`);
      }
    });
  });

  render();
}

import { animateNumber, int, lives } from './format.js';

const SVG_NS = 'http://www.w3.org/2000/svg';
const MAX_PER_RING = 420;

export function initRipple() {
  const svg = document.querySelector('#ripple-svg');
  if (!svg) return;

  const peopleInput = document.querySelector('#people');
  const depthInput = document.querySelector('#depth');
  const peopleOut = document.querySelector('#people-out');
  const depthOut = document.querySelector('#depth-out');
  const badge = document.querySelector('#ripple-badge');
  const peopleEl = document.querySelector('#ripple-people');
  const moneyEl = document.querySelector('#ripple-money');
  const qalyEl = document.querySelector('#ripple-qaly');
  const livesEl = document.querySelector('#ripple-lives');

  const people = () => Number(peopleInput.value);
  const depth = () => Number(depthInput.value);

  function setFill(input) {
    const min = Number(input.min) || 0;
    const max = Number(input.max) || 100;
    const pct = ((Number(input.value) - min) / (max - min)) * 100;
    input.style.setProperty('--fill', `${pct}%`);
  }

  function totalReach() {
    const p = people();
    const d = depth();
    let sum = 0;
    let level = 1;
    for (let i = 1; i <= d; i++) {
      level *= p;
      sum += level;
    }
    return { sum, p, d };
  }

  function orbit(n, radius, levelSeed) {
    const pts = [];
    const step = Math.max(1, Math.ceil(n / MAX_PER_RING));
    const shown = Math.ceil(n / step);
    for (let i = 0; i < shown; i++) {
      const idx = i * step;
      const angle = (idx / n) * Math.PI * 2 - Math.PI / 2 + levelSeed * 0.6;
      const jitter = (hash(idx + levelSeed * 97) - 0.5) * 7;
      pts.push({
        x: 300 + Math.cos(angle) * (radius + jitter),
        y: 300 + Math.sin(angle) * (radius + jitter),
        i: idx,
      });
    }
    return pts;
  }

  function render() {
    const { sum, p, d } = totalReach();
    peopleOut.textContent = String(p);
    depthOut.textContent = String(d);
    setFill(peopleInput);
    setFill(depthInput);

    badge.textContent = `${int(sum)} PEOPLE`;
    animateNumber(peopleEl, sum, (v) => int(v), 550);
    animateNumber(moneyEl, sum * 100, (v) => '$' + int(v), 550);
    animateNumber(qalyEl, sum, (v) => int(v), 550);
    animateNumber(livesEl, sum / 45, (v) => '≈ ' + (v >= 10 ? int(v) : v.toFixed(1)), 550);

    svg.innerHTML = '';

    // faint guide rings
    for (let k = 1; k <= d; k++) {
      const ring = document.createElementNS(SVG_NS, 'circle');
      ring.setAttribute('cx', '300');
      ring.setAttribute('cy', '300');
      ring.setAttribute('r', String(60 + k * 44));
      ring.setAttribute('fill', 'none');
      ring.setAttribute('stroke', 'rgba(241,239,229,0.07)');
      ring.setAttribute('stroke-dasharray', '2 6');
      svg.append(ring);
    }

    let level = 1;
    const colors = ['#d8f26b', '#a9df76', '#7ce0cf', '#8fc7cf', '#f0a35e', '#ef8b7c'];
    for (let k = 1; k <= d; k++) {
      level *= p;
      const radius = 60 + k * 44;
      const pts = orbit(level, radius, k);
      const baseR = Math.max(1.5, 6.2 - k * 0.7);
      const dotR = level > MAX_PER_RING ? baseR * 0.72 : baseR;
      pts.forEach((pt, idx) => {
        const c = document.createElementNS(SVG_NS, 'circle');
        c.setAttribute('cx', pt.x.toFixed(2));
        c.setAttribute('cy', pt.y.toFixed(2));
        c.setAttribute('r', '0');
        c.setAttribute('fill', colors[(k - 1) % colors.length]);
        c.setAttribute('opacity', '0');
        svg.append(c);
        setTimeout(() => {
          c.setAttribute('r', String(dotR));
          c.setAttribute('opacity', String(0.42 + (k === 1 ? 0.5 : 0.28)));
        }, Math.min(600, k * 55 + idx * 0.5));
      });
    }

    // center: you
    const halo = document.createElementNS(SVG_NS, 'circle');
    halo.setAttribute('cx', '300');
    halo.setAttribute('cy', '300');
    halo.setAttribute('r', '22');
    halo.setAttribute('fill', 'rgba(216,242,107,0.1)');
    svg.append(halo);

    const you = document.createElementNS(SVG_NS, 'circle');
    you.setAttribute('cx', '300');
    you.setAttribute('cy', '300');
    you.setAttribute('r', '7');
    you.setAttribute('fill', '#d8f26b');
    svg.append(you);

    const label = document.createElementNS(SVG_NS, 'text');
    label.setAttribute('x', '300');
    label.setAttribute('y', '272');
    label.setAttribute('text-anchor', 'middle');
    label.setAttribute('fill', '#a5a598');
    label.setAttribute('font-family', 'SFMono-Regular, Menlo, monospace');
    label.setAttribute('font-size', '9');
    label.setAttribute('letter-spacing', '2');
    label.textContent = 'YOU';
    svg.append(label);
  }

  peopleInput.addEventListener('input', render);
  depthInput.addEventListener('input', render);
  render();
}

function hash(n) {
  const x = Math.sin(n * 127.1 + 311.7) * 43758.5453;
  return x - Math.floor(x);
}

import { initHero } from './src/hero.js';
import { initLab } from './src/lab.js';
import { initAtlas } from './src/atlas.js';
import { initPortfolio } from './src/portfolio.js';
import { initRipple } from './src/ripple.js';

function initReveal() {
  const targets = document.querySelectorAll(
    '.section-head, .ledger, .ledger-row, .lab-grid, .atlas-toolbar, .atlas-grid, .portfolio-panel, .ripple-grid, .method-grid, .fineprint'
  );
  targets.forEach((el) => el.classList.add('reveal'));

  if (!('IntersectionObserver' in window)) {
    targets.forEach((el) => el.classList.add('in'));
    return;
  }

  const io = new IntersectionObserver((entries) => {
    entries.forEach((entry) => {
      if (entry.isIntersecting) {
        entry.target.classList.add('in');
        io.unobserve(entry.target);
      }
    });
  }, { threshold: 0.08, rootMargin: '0px 0px -40px 0px' });

  targets.forEach((el, i) => {
    el.style.transitionDelay = `${Math.min(i % 6, 5) * 45}ms`;
    io.observe(el);
  });
}

function initNav() {
  const links = [...document.querySelectorAll('.nav-links a')];
  const sections = links
    .map((a) => document.querySelector(a.getAttribute('href')))
    .filter(Boolean);

  if (!sections.length || !('IntersectionObserver' in window)) return;

  const io = new IntersectionObserver((entries) => {
    entries.forEach((entry) => {
      if (!entry.isIntersecting) return;
      links.forEach((a) => {
        const active = a.getAttribute('href') === '#' + entry.target.id;
        a.style.color = active ? 'var(--ink)' : '';
      });
    });
  }, { rootMargin: '-40% 0px -55% 0px' });

  sections.forEach((s) => io.observe(s));
}

initHero();
initLab();
initPortfolio();
initAtlas();
initRipple();
initReveal();
initNav();

